void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;



    // assign a texture to a vector
    // texture is the webcam
    vec3 col = vec3(texture(iChannel0, uv).xyz); 

    // standard values for gray scale conversion
    vec3 nrl = vec3(0.2126,0.7152, 0.0722);
    // method to get the gray scale value
    float grayVal = (col.x * nrl.x) + (col.y*nrl.y) + (col.z*nrl.z);

    float scanLineY = cos(sin(uv.y * iResolution.y - sin(iTime))*2.0 );
    //float scanLineX = cos(sin(uv.x * iResolution.x - sin(iTime))*6.0 );




    // make the gray scale value into a color
    vec3 finalColor = vec3(grayVal, grayVal, grayVal) * scanLineY* 2.0; //* scanLineX;

    // output
    fragColor = vec4(finalColor, 1);

}
